def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    my = [h[0] for h in history]
    op = [h[1] for h in history]

    my_def_streak = 0
    for a in reversed(my):
        if a == 'D': my_def_streak += 1
        else: break
    op_def_streak = 0
    for a in reversed(op):
        if a == 'D': op_def_streak += 1
        else: break

    last_my = my[-1]
    last_op = op[-1]

    if n >= 99:
        return 'D'
    if n == 98:
        ret = sum(1 for i in range(n-1) if my[i] == 'D' and op[i+1] == 'D')
        tot = sum(1 for i in range(n-1) if my[i] == 'D')
        if tot > 0 and ret / tot > 0.5:
            return 'C'
        return 'D'

    if my_def_streak >= 3 and last_op == 'D' and op_def_streak >= 3:
        return 'C'

    if last_op == 'D':
        if op_def_streak >= 2:
            return 'D'
        return 'C'

    if last_my == 'D' and last_op == 'C':
        ret = 0
        exp = 0
        for i in range(n-1):
            if my[i] == 'D' and i > 0 and op[i-1] == 'C':
                if op[i+1] == 'D':
                    ret += 1
                else:
                    exp += 1
        if ret + exp > 0 and ret / (ret + exp) > 0.5:
            return 'C'
        else:
            return 'D'

    if last_my == 'C' and last_op == 'C':
        if n >= 2 and my[-2] == 'D' and op[-2] == 'C':
            return 'D'
        if n > 10 and n < 90:
            cc_streak = 0
            for i in range(n-1, -1, -1):
                if my[i] == 'C' and op[i] == 'C':
                    cc_streak += 1
                else:
                    break
            if cc_streak >= 10 and rng.random() < 0.1:
                return 'D'
        return 'C'

    return 'C'
